package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.RadioKernel;import net.minecraft.network.chat.Component;import net.minecraft.core.BlockPos;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** Four-channel low-bandwidth transmitter. Neighbor redstone strength is the transmitted payload, not merely an on/off enable. */
public class RadioTransmitterBlock extends Block{public static final IntegerProperty CHANNEL=IntegerProperty.create("channel",0,3);public RadioTransmitterBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(CHANNEL,0));}@Override public MapCodec<RadioTransmitterBlock> codec(){return RedstoneEngineering.RADIO_TRANSMITTER_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(CHANNEL);}private int payload(Level l,BlockPos p){return Math.max(0,Math.min(15,l.getBestNeighborSignal(p)));}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);RadioKernel.updateTransmitter(l,p,s.getValue(CHANNEL),payload(l,p));}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos q,boolean m){RadioKernel.updateTransmitter(l,p,s.getValue(CHANNEL),payload(l,p));}@Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState n,boolean m){if(!s.is(n.getBlock()))RadioKernel.removeTransmitter(l,p);super.onRemove(s,l,p,n,m);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int c=(s.getValue(CHANNEL)+1)%4;BlockState ns=s.setValue(CHANNEL,c);l.setBlock(p,ns,Block.UPDATE_CLIENTS);RadioKernel.updateTransmitter(l,p,c,payload(l,p));pl.displayClientMessage(Component.literal("Radio TX channel="+c+" payload="+payload(l,p)+"/15 range="+RadioKernel.RANGE),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
